// 1. Validate incoming payload
const body = $input.item.json.body || $input.item.json;
const question = (body.question || '').trim();
const sessionId = body.session_id || 'sess_' + Date.now();
const channel = body.channel || 'pwa';

if (!question) {
  throw new Error('Missing parameter: question is required');
}

// 2. Check for Prompt Injection
const injectionRegex = /ignore\s+(previous|prior|above|all)\s+(instructions|rules|prompts|guidelines)|disregard\s+the\s+(database|rules)|tell\s+me\s+what\s+the\s+tax\s+law\s+really\s+is/i;
const isInjection = injectionRegex.test(question);

return {
  json: {
    sessionId,
    question,
    channel,
    isInjection,
    timestamp: new Date().toISOString()
  }
};

// Calculate vector cosine similarity and fuzzy string matching
const question = $('Validate & Detect Injection').first().json.question.toLowerCase().trim();
const allRows = $input.all().map(item => item.json);

function calculateCosineSimilarity(str1, str2) {
  const stopWords = new Set(['is', 'a', 'the', 'am', 'i', 'to', 'for', 'in', 'of', 'on', 'at', 'what', 'how', 'check', 'if', 'my', 'are', 'you', 'we', 'they', 'he', 'she', 'it', 'and', 'or', 'but', 'can', 'do', 'does', 'did', 'about', 'with', 'by']);
  const getTokens = (text) => text.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()?]/g, '').split(/\s+/).filter(t => t.length > 2 && !stopWords.has(t));
  const tokens1 = getTokens(str1);
  const tokens2 = getTokens(str2);
  if (tokens1.length === 0 || tokens2.length === 0) return 0;
  const map1 = {}, map2 = {};
  tokens1.forEach(t => map1[t] = (map1[t] || 0) + 1);
  tokens2.forEach(t => map2[t] = (map2[t] || 0) + 1);
  let dotProduct = 0;
  const allWords = new Set([...Object.keys(map1), ...Object.keys(map2)]);
  for (const word of allWords) {
    if (map1[word] && map2[word]) dotProduct += map1[word] * map2[word];
  }
  const mag1 = Math.sqrt(Object.values(map1).reduce((s, v) => s + v * v, 0));
  const mag2 = Math.sqrt(Object.values(map2).reduce((s, v) => s + v * v, 0));
  if (mag1 === 0 || mag2 === 0) return 0;
  return dotProduct / (mag1 * mag2);
}

function calculateFuzzySimilarity(q, target) {
  if (!q || !target) return 0;
  q = q.toLowerCase().trim();
  target = target.toLowerCase().trim();
  if (q === target) return 100;
  if (target.includes(q) || q.includes(target)) return 85;
  const cosine = calculateCosineSimilarity(q, target);
  return Math.round(cosine * 100);
}

const scoredRows = allRows.map(row => {
  const rowQ = row.user_question || '';
  const variations = (row.question_variations || '').split('|');
  const keywords = (row.keywords || '').split(',');
  const candidates = [rowQ, ...variations, keywords.join(' '), row.category || ''];

  let bestScore = 0;
  for (const c of candidates) {
    const s = calculateFuzzySimilarity(question, c);
    if (s > bestScore) bestScore = s;
  }
  return { row, score: bestScore };
});

scoredRows.sort((a, b) => b.score - a.score);

// Enforce strict 70% (0.70) similarity threshold requirement
const SIMILARITY_THRESHOLD = 70;
const validMatches = scoredRows.filter(r => r.score >= SIMILARITY_THRESHOLD).map(r => r.row);
const topScore = scoredRows[0]?.score || 0;
const isOutOfScope = validMatches.length === 0 || topScore < SIMILARITY_THRESHOLD;

return {
  json: {
    question: $('Validate & Detect Injection').first().json.question,
    sessionId: $('Validate & Detect Injection').first().json.sessionId,
    channel: $('Validate & Detect Injection').first().json.channel,
    matches: validMatches.slice(0, 3),
    confidence: isOutOfScope ? 0 : Math.min(1.0, topScore / 100),
    isOutOfScope
  }
};

