const geminiText = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const matches = $('Rank & Filter Matches').first().json.matches || [];
const primary = matches[0] || {};

const disclaimer = 'Consult your CA for a case-specific position.';
let finalAnswer = geminiText.trim();
if (!finalAnswer.includes(disclaimer)) {
  finalAnswer += '\n\n' + disclaimer;
}

const sources = matches.map(m => ({
  provision: m.act_or_regulation + ' - ' + m.section_rule_regulation,
  authority: m.source_authority,
  source: m.source_type,
  url: m.source_url,
  applicable_period: m.relevant_FY,
  excerpt: m.source_excerpt_or_summary
}));

return {
  json: {
    answer: finalAnswer,
    sources,
    topic: primary.category || 'General NRI Advisory',
    matched_faq_ids: matches.map(m => m.faq_id),
    out_of_scope: false,
    escalation_required: primary.professional_review_required === 'YES',
    disclaimer
  }
};
